<?php

namespace App\Http\Controllers;

use App\Models\Setting;
use App\Services\ActivityLogger;
use Illuminate\Http\Request;
use Illuminate\Support\Str;

class SettingsController extends Controller
{
    public function index(){return view('settings.index',['settings'=>collect(['country','business_provider','website_search_provider','exact_postcode_match','max_api_requests_per_minute','max_search_requests_per_minute','max_crawl_requests_per_minute','request_delay_ms','request_timeout','max_pages_per_website','max_crawl_depth','max_concurrent_jobs','retry_attempts','retry_delay','website_confidence_threshold','recheck_websites_after_days','recheck_no_email_after_days','never_recheck_success','email_preference_order'])->mapWithKeys(fn($k)=>[$k=>Setting::valueOf($k)]),'hasYelp'=>filled(Setting::valueOf('yelp_api_key',config('services.yelp.key'))),'hasFoursquare'=>filled(Setting::valueOf('foursquare_api_key',config('services.foursquare.key'))),'hasGoogle'=>filled(Setting::valueOf('google_search_api_key',config('services.google_search.key')))&&filled(Setting::valueOf('google_search_engine_id',config('services.google_search.engine_id'))),'hasApiToken'=>filled(Setting::valueOf('api_token'))]);}
    public function update(Request$r,ActivityLogger$a){$data=$r->validate(['country'=>'required|string|size:2','business_provider'=>'required|in:yelp,foursquare','website_search_provider'=>'required|in:google_cse','exact_postcode_match'=>'sometimes|boolean','max_api_requests_per_minute'=>'required|integer|min:1|max:500','max_search_requests_per_minute'=>'required|integer|min:1|max:500','max_crawl_requests_per_minute'=>'required|integer|min:1|max:500','request_delay_ms'=>'required|integer|min:0|max:60000','request_timeout'=>'required|integer|min:3|max:120','max_pages_per_website'=>'required|integer|min:1|max:50','max_crawl_depth'=>'required|integer|min:0|max:5','max_concurrent_jobs'=>'required|integer|min:1|max:5','retry_attempts'=>'required|integer|min:1|max:10','retry_delay'=>'required|integer|min:10|max:86400','website_confidence_threshold'=>'required|integer|min:1|max:100','recheck_websites_after_days'=>'required|integer|min:1|max:3650','recheck_no_email_after_days'=>'required|integer|min:1|max:3650','never_recheck_success'=>'sometimes|boolean','email_preference_order'=>'required|string|max:500','yelp_api_key'=>'nullable|string|max:1000','foursquare_api_key'=>'nullable|string|max:1000','google_search_api_key'=>'nullable|string|max:1000','google_search_engine_id'=>'nullable|string|max:500']);foreach($data as$key=>$value){if(in_array($key,['yelp_api_key','foursquare_api_key','google_search_api_key','google_search_engine_id'],true)){if(filled($value))Setting::put($key,$value,'apis',true);}else Setting::put($key,$value,'general');}foreach(['exact_postcode_match','never_recheck_success']as$key)if(!$r->has($key))Setting::put($key,false,'general');$a->log('settings.updated','Application settings updated.');return back()->with('success','Settings saved.');}
    public function generateApiToken(){Setting::put('api_token',Str::random(64),'apis',true);return back()->with('success','A new API token was generated. Copy it now from the one-time value shown below.')->with('new_api_token',Setting::valueOf('api_token'));}
}
